CREATE TABLE "EpisodicMemory" ("id" TEXT PRIMARY KEY, "userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE, "category" TEXT NOT NULL, "summary" TEXT NOT NULL, "referenceType" TEXT, "referenceId" TEXT, "source" TEXT NOT NULL, "retentionUntil" TIMESTAMPTZ, "deletedAt" TIMESTAMPTZ, "createdAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Workflow" ("id" TEXT PRIMARY KEY, "userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE, "type" TEXT NOT NULL, "status" TEXT NOT NULL, "currentStep" TEXT, "idempotencyKey" TEXT, "approvalStatus" TEXT NOT NULL DEFAULT 'NOT_REQUIRED', "retryCount" INTEGER NOT NULL DEFAULT 0, "deadlineAt" TIMESTAMPTZ, "createdAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE("userId", "idempotencyKey"));
CREATE TABLE "WorkflowStep" ("id" TEXT PRIMARY KEY, "workflowId" TEXT NOT NULL REFERENCES "Workflow"("id") ON DELETE CASCADE, "stepKey" TEXT NOT NULL, "status" TEXT NOT NULL, "dependsOn" JSONB NOT NULL, "input" JSONB, "result" JSONB, "errorCode" TEXT, "retryCount" INTEGER NOT NULL DEFAULT 0, "startedAt" TIMESTAMPTZ, "completedAt" TIMESTAMPTZ, UNIQUE("workflowId", "stepKey"));
CREATE TABLE "Approval" ("id" TEXT PRIMARY KEY, "userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE, "actionType" TEXT NOT NULL, "payloadHash" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'PENDING', "expiresAt" TIMESTAMPTZ NOT NULL, "consumedAt" TIMESTAMPTZ, "createdAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "MonitoredPlan" ("id" TEXT PRIMARY KEY, "userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE, "workflowId" TEXT, "eventId" TEXT, "origin" TEXT NOT NULL, "destination" TEXT NOT NULL, "baselineTravelMinutes" INTEGER NOT NULL, "thresholdMinutes" INTEGER NOT NULL DEFAULT 10, "enabled" BOOLEAN NOT NULL DEFAULT TRUE, "quietHours" JSONB, "lastNotificationFingerprint" TEXT, "nextCheckAt" TIMESTAMPTZ, "createdAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "BackgroundJob" ("id" TEXT PRIMARY KEY, "type" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'PENDING', "payload" JSONB NOT NULL, "attempts" INTEGER NOT NULL DEFAULT 0, "maxAttempts" INTEGER NOT NULL DEFAULT 3, "runAt" TIMESTAMPTZ NOT NULL, "lastErrorCode" TEXT, "lockedAt" TIMESTAMPTZ, "createdAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "ProviderHealth" ("provider" TEXT PRIMARY KEY, "state" TEXT NOT NULL DEFAULT 'CLOSED', "consecutiveFailures" INTEGER NOT NULL DEFAULT 0, "openedAt" TIMESTAMPTZ, "lastFailureAt" TIMESTAMPTZ, "updatedAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "EpisodicMemory_userId_category_createdAt_idx" ON "EpisodicMemory"("userId", "category", "createdAt");
CREATE INDEX "Workflow_userId_status_createdAt_idx" ON "Workflow"("userId", "status", "createdAt");
CREATE INDEX "WorkflowStep_workflowId_status_idx" ON "WorkflowStep"("workflowId", "status");
CREATE INDEX "Approval_userId_status_expiresAt_idx" ON "Approval"("userId", "status", "expiresAt");
CREATE INDEX "MonitoredPlan_enabled_nextCheckAt_idx" ON "MonitoredPlan"("enabled", "nextCheckAt");
CREATE INDEX "BackgroundJob_status_runAt_idx" ON "BackgroundJob"("status", "runAt");
